import { expect, test, type Page } from "@playwright/test"
import { PERMISSION } from "../src/modules/accesscontrol/permissions"
import { mockBackend, ORGANIZATION_ID } from "./support/mock-backend"

const ORGANIZATION_URL = `/organizations/${ORGANIZATION_ID}`

async function fillAgreementForm(page: Page, name: string) {
  const dialog = page.getByRole("dialog")
  await expect(dialog.getByRole("checkbox", { name: "Khám tổng quát" })).toBeVisible()
  // The agreement code is generated by the system, so the form never shows or asks for it.
  await expect(dialog.getByLabel(/Mã thỏa thuận/)).toHaveCount(0)
  // The day and the site belong to the sessions: the agreement only has a validity period.
  await expect(dialog.getByLabel(/Loại địa điểm/)).toHaveCount(0)
  await expect(dialog.getByRole("button", { name: "Thêm ngày" })).toHaveCount(0)
  await dialog.getByLabel(/Tên thỏa thuận/).fill(name)
  await dialog.getByLabel(/^Áp dụng từ ngày/).fill("2026-10-01")
  await dialog.getByLabel(/^Áp dụng đến ngày/).fill("2026-12-31")
  await dialog.getByRole("checkbox", { name: "Khám tổng quát" }).check()
}

test("create, view, edit and delete an agreement through the real UI flow", async ({ page }) => {
  const backend = await mockBackend(page)
  await page.goto(ORGANIZATION_URL)
  await expect(page.getByText("Chưa có thỏa thuận nào cho đơn vị này")).toBeVisible()

  await page.getByRole("button", { name: "Tạo thỏa thuận" }).first().click()
  await fillAgreementForm(page, "Khám định kỳ E2E")
  await page.getByRole("dialog").getByRole("button", { name: "Tạo thỏa thuận" }).click()

  await expect(page).toHaveURL(new RegExp(`/organizations/${ORGANIZATION_ID}/agreements/[^/]+$`))
  await expect(page.getByRole("heading", { name: "Khám định kỳ E2E" })).toBeVisible()
  await expect(page.getByText("Nháp").first()).toBeVisible()
  await expect(page.getByText("01/10/2026 – 31/12/2026").first()).toBeVisible()
  await expect(page.getByText("Khám tổng quát").first()).toBeVisible()
  expect(backend.agreements[0]).toMatchObject({ validFrom: "2026-10-01", validTo: "2026-12-31" })
  expect(backend.agreements[0].services).toEqual([
    expect.objectContaining({ serviceId: expect.any(String), negotiatedPrice: 150000 }),
  ])

  await page.getByRole("button", { name: "Chỉnh sửa" }).click()
  const dialog = page.getByRole("dialog")
  await expect(dialog.getByRole("checkbox", { name: "Khám tổng quát" })).toBeChecked()
  await expect(dialog.getByLabel(/Mã thỏa thuận/)).toHaveCount(0)
  await dialog.getByLabel(/Tên thỏa thuận/).fill("Khám định kỳ E2E (đã sửa)")
  await dialog.getByRole("button", { name: "Lưu thay đổi" }).click()
  await expect(page.getByRole("heading", { name: "Khám định kỳ E2E (đã sửa)" })).toBeVisible()
  expect(backend.agreements[0].rowVersion).toBe(1)

  await page.getByRole("button", { name: "Xóa thỏa thuận" }).click()
  await page.getByRole("button", { name: "Xác nhận xóa" }).click()
  await expect(page).toHaveURL(new RegExp(`/organizations/${ORGANIZATION_ID}$`))
  await expect(page.getByText("Chưa có thỏa thuận nào cho đơn vị này")).toBeVisible()
  expect(backend.agreements).toHaveLength(0)
  expect(backend.unexpected).toEqual([])
})

test("activates an agreement and then locks its services", async ({ page }) => {
  const backend = await mockBackend(page)
  const agreement = backend.seedAgreement()
  await page.goto(`${ORGANIZATION_URL}/agreements/${agreement.id}`)

  await page.getByRole("button", { name: "Kích hoạt thỏa thuận" }).click()
  await page.getByRole("dialog").getByRole("button", { name: "Kích hoạt thỏa thuận" }).click()
  await expect(page.getByText("Đang áp dụng").first()).toBeVisible()
  // Basic information is fixed once the agreement applies.
  await expect(page.getByRole("button", { name: "Chỉnh sửa" })).toHaveCount(0)
  await expect(page.getByRole("button", { name: "Xóa thỏa thuận" })).toHaveCount(0)
  expect(backend.requests.find((request) => request.path.endsWith("/activate"))?.body).toEqual({ rowVersion: 0 })

  // Services are fixed once the examination starts.
  await expect(page.getByRole("button", { name: "Thêm dịch vụ" })).toHaveCount(0)
  await expect(page.getByRole("button", { name: /^Ngừng dịch vụ/ })).toHaveCount(0)
  expect(backend.agreements[0].services).toHaveLength(1)
  expect(backend.unexpected).toEqual([])
})

test("ends an active agreement and then offers no change", async ({ page }) => {
  const backend = await mockBackend(page)
  const agreement = backend.seedAgreement({ status: "ACTIVE", rowVersion: 3 })
  await page.goto(`${ORGANIZATION_URL}/agreements/${agreement.id}`)

  await page.getByRole("button", { name: "Kết thúc thỏa thuận" }).click()
  await page.getByRole("dialog").getByRole("button", { name: "Kết thúc thỏa thuận" }).click()

  await expect(page.getByText("Đã kết thúc").first()).toBeVisible()
  await expect(page.getByRole("button", { name: "Thêm dịch vụ" })).toHaveCount(0)
  await expect(page.getByRole("button", { name: /^Ngừng dịch vụ/ })).toHaveCount(0)
  await expect(page.getByRole("button", { name: "Kết thúc thỏa thuận" })).toHaveCount(0)
  expect(backend.requests.find((request) => request.path.endsWith("/end"))?.body).toEqual({ rowVersion: 3 })
})

test("an update conflict keeps the form and only reloads when asked", async ({ page }) => {
  const backend = await mockBackend(page)
  const agreement = backend.seedAgreement({ name: "Thỏa thuận gốc" })
  await page.goto(`${ORGANIZATION_URL}/agreements/${agreement.id}`)

  await page.getByRole("button", { name: "Chỉnh sửa" }).click()
  const dialog = page.getByRole("dialog")
  await expect(dialog.getByRole("checkbox", { name: "Khám tổng quát" })).toBeChecked()
  await dialog.getByLabel(/Tên thỏa thuận/).fill("Tên tôi vừa nhập")
  backend.conflictNextUpdate()
  await dialog.getByRole("button", { name: "Lưu thay đổi" }).click()

  await expect(dialog.getByText(/Dữ liệu đã thay đổi hoặc không thỏa quy tắc nghiệp vụ/)).toBeVisible()
  await expect(dialog.getByLabel(/Tên thỏa thuận/)).toHaveValue("Tên tôi vừa nhập")
  expect(backend.requests.filter((request) => request.method === "PUT")).toHaveLength(1)

  await dialog.getByRole("button", { name: "Tải lại dữ liệu mới nhất" }).click()
  await expect(dialog.getByLabel(/Tên thỏa thuận/)).toHaveValue("Thỏa thuận gốc (đã sửa bởi người khác)")
  expect(backend.requests.filter((request) => request.method === "PUT")).toHaveLength(1)
})

test("a delete conflict explains why and offers a reload instead of resending", async ({ page }) => {
  const backend = await mockBackend(page)
  const agreement = backend.seedAgreement()
  await page.goto(`${ORGANIZATION_URL}/agreements/${agreement.id}`)

  backend.conflictNextDelete()
  await page.getByRole("button", { name: "Xóa thỏa thuận" }).click()
  await page.getByRole("button", { name: "Xác nhận xóa" }).click()
  await expect(page.getByRole("alert").filter({ hasText: "đã có người khám" })).toBeVisible()
  expect(backend.requests.filter((request) => request.method === "DELETE")).toHaveLength(1)

  await page.getByRole("button", { name: "Tải lại dữ liệu mới nhất" }).click()
  await page.keyboard.press("Escape")
  await expect(page.getByRole("button", { name: "Xóa thỏa thuận" })).toHaveCount(0)
  expect(backend.requests.filter((request) => request.method === "DELETE")).toHaveLength(1)
})

test("an account that can only read sees the agreement but none of the actions", async ({ page }) => {
  const backend = await mockBackend(page, {
    permissions: [
      PERMISSION.ORGANIZATION_VIEW,
      PERMISSION.HEALTH_EXAMINATION_AGREEMENT_VIEW,
      PERMISSION.HEALTH_EXAMINATION_AGREEMENT_DETAIL_VIEW,
    ],
  })
  const agreement = backend.seedAgreement()
  await page.goto(`${ORGANIZATION_URL}/agreements/${agreement.id}`)

  await expect(page.getByRole("heading", { name: agreement.name })).toBeVisible()
  for (const name of ["Chỉnh sửa", "Xóa thỏa thuận", "Kích hoạt thỏa thuận", "Kết thúc thỏa thuận", "Thêm dịch vụ"]) {
    await expect(page.getByRole("button", { name })).toHaveCount(0)
  }
  // No permission for the schedule, the roster or the report: the tabs are left out.
  await expect(page.getByRole("button", { name: "Lịch khám" })).toHaveCount(0)
  await expect(page.getByRole("button", { name: "Báo cáo" })).toHaveCount(0)
  expect(backend.unexpected).toEqual([])
})

test("a missing agreement shows a not-found state with a way back", async ({ page }) => {
  const backend = await mockBackend(page)
  await page.goto(`${ORGANIZATION_URL}/agreements/does-not-exist`)
  await expect(page.getByText("Không tìm thấy thỏa thuận")).toBeVisible()
  await page.getByRole("link", { name: /Về danh sách thỏa thuận/ }).click()
  await expect(page).toHaveURL(new RegExp(`/organizations/${ORGANIZATION_ID}$`))
  expect(backend.unexpected).toEqual([])
})

test("a forbidden list shows a Vietnamese message, not the backend text", async ({ page }) => {
  const backend = await mockBackend(page)
  backend.failList(403)
  await page.goto(ORGANIZATION_URL)
  await expect(
    page.getByRole("alert").filter({ hasText: "Không được phép thực hiện thao tác này." })
  ).toBeVisible()
  await expect(page.getByText("Forbidden by test")).toHaveCount(0)
  backend.clearListFailure()
  await page.getByRole("button", { name: "Thử lại" }).click()
  await expect(page.getByText("Chưa có thỏa thuận nào cho đơn vị này")).toBeVisible()
})
